package com.wutsi.ndopify.npc

import com.fasterxml.jackson.databind.ObjectMapper
import org.junit.jupiter.api.Test
import java.awt.image.BufferedImage
import java.io.ByteArrayInputStream
import java.security.MessageDigest
import javax.imageio.ImageIO
import kotlin.math.abs
import kotlin.math.hypot
import kotlin.test.assertEquals
import kotlin.test.assertFalse
import kotlin.test.assertTrue
import kotlin.test.fail

/** Checks the static PWA files served from `public/` and the worker generated by `build-assets.mjs`. */
class PwaAssetsTest {
    private companion object {
        const val BLUE = 0x1d7edf
        const val WHITE = 0xffffff

        /** A visible pixel whose darkest channel is at least this is a white fringe, not the mark. */
        const val VISIBLE_WHITE = 0xE0
    }

    @Test
    fun manifestIsValidJsonWithTheInstallableIconSet() {
        val json = ObjectMapper().readTree(resource("public/manifest.json"))
        assertEquals("Ndopify Partner Central", json["name"].asText())
        assertEquals("Ndopify Partner", json["short_name"].asText())
        assertEquals("/", json["start_url"].asText())
        assertEquals("/", json["scope"].asText())
        assertEquals("standalone", json["display"].asText())
        assertEquals("fr", json["lang"].asText())

        val icons = json["icons"].map { it["src"].asText() to it["purpose"].asText() }
        assertEquals(
            listOf(
                "/assets/images/icon-192.png" to "any",
                "/assets/images/icon-512.png" to "any",
                "/assets/images/icon-maskable-192.png" to "maskable",
                "/assets/images/icon-maskable-512.png" to "maskable",
            ),
            icons,
        )
    }

    @Test
    fun declaredIconsExistWithTheirDeclaredDimensions() {
        val json = ObjectMapper().readTree(resource("public/manifest.json"))
        json["icons"].forEach { icon ->
            val (width, height) = icon["sizes"].asText().split("x").map(String::toInt)
            assertEquals(width to height, pngSize(resourceBytes("public" + icon["src"].asText())))
        }
        assertEquals(180 to 180, pngSize(resourceBytes("public/assets/images/apple-touch-icon.png")))
    }

    @Test
    fun faviconsAreTransparentAroundTheDisc() {
        faviconImages().forEach { (name, icon) ->
            assertTransparentBorder(name, icon)
            assertNoVisibleWhite(name, icon)
            assertEquals(0xFF, icon.getRGB(icon.width / 2, icon.height / 2) ushr 24, "$name has no opaque centre")
        }
    }

    @Test
    fun faviconMasterIsTheSuppliedArtworkWithoutItsBackground() {
        val master = image("public/assets/images/favicon.png")
        assertEquals(500 to 500, master.width to master.height)
        assertEquals(BLUE, rgb(master, 250, 250)) // the disc
        assertEquals(0x000000, rgb(master, 250, 130)) // the roof
        assertEquals(BLUE, rgb(master, 250, 60))
        assertEquals(0, master.getRGB(0, 0) ushr 24) // the source's white square is gone
        assertEquals(0, master.getRGB(250, 13) ushr 24) // outside the cut (radius 236: the disc starts at y = 14)
        assertEquals(0xFF, master.getRGB(250, 15) ushr 24) // just inside it: opaque, no white fringe
    }

    @Test
    fun faviconFilesHaveTheirSizes() {
        assertEquals(500 to 500, pngSize(resourceBytes("public/assets/images/favicon.png")))
        assertEquals(16 to 16, pngSize(resourceBytes("public/assets/images/favicon-16.png")))
        assertEquals(32 to 32, pngSize(resourceBytes("public/assets/images/favicon-32.png")))
    }

    @Test
    fun faviconIcoCarriesThreeTransparentLayers() {
        val bytes = resourceBytes("public/favicon.ico")
        assertEquals(listOf(0, 0, 1, 0), bytes.take(4).map { it.toInt() and 0xff }, "not an ICO header")
        assertEquals(3, bytes[4].toInt() and 0xff, "the ICO must carry 16, 32 and 48")
        val layers = icoLayers()
        assertEquals(listOf(16, 32, 48), layers.map { it.size })
        assertEquals(listOf(32, 32, 32), layers.map { it.bitCount }, "a layer without alpha (32 bpp) loses the transparency")
        layers.forEach { layer ->
            assertEquals(layer.size, layer.image.width, "the ${layer.size}px layer decodes to ${layer.image.width}px")
            assertEquals(layer.size, layer.image.height, "the ${layer.size}px layer decodes to ${layer.image.height}px")
        }
    }

    @Test
    fun masterIconIsTheSuppliedArtwork() {
        val master = image("public/assets/images/icon.png")
        assertEquals(500 to 500, master.width to master.height)
        assertEquals(WHITE, rgb(master, 0, 0)) // opaque white square (not the old transparent corner)
        assertEquals(BLUE, rgb(master, 250, 30)) // the blue circle
        assertEquals(0x000000, rgb(master, 250, 250)) // the black house/N
        assertEquals(WHITE, rgb(master, 245, 140)) // the white window
    }

    @Test
    fun rebuiltIconsHaveTheirSizeAndComposition() {
        assertEquals(192 to 192, pngSize(resourceBytes("public/assets/images/icon-192.png")))
        assertEquals(512 to 512, pngSize(resourceBytes("public/assets/images/icon-512.png")))
        assertEquals(192 to 192, pngSize(resourceBytes("public/assets/images/icon-maskable-192.png")))
        assertEquals(512 to 512, pngSize(resourceBytes("public/assets/images/icon-maskable-512.png")))
        assertEquals(180 to 180, pngSize(resourceBytes("public/assets/images/apple-touch-icon.png")))

        val any = image("public/assets/images/icon-512.png")
        assertEquals(WHITE, rgb(any, 0, 0)) // "any" keeps the white corner
        assertEquals(BLUE, rgb(any, 256, 20))
        assertEquals(0x000000, rgb(any, 256, 256))

        listOf(
            "public/assets/images/icon-maskable-192.png",
            "public/assets/images/icon-maskable-512.png",
            "public/assets/images/apple-touch-icon.png",
        ).forEach { path ->
            val tile = image(path)
            val last = tile.width - 1
            listOf(0 to 0, last to 0, 0 to last, last to last).forEach { (x, y) ->
                assertEquals(BLUE, rgb(tile, x, y), "$path is not full bleed at ($x,$y)")
            }
        }
    }

    @Test
    fun maskableContentStaysInsideTheSafeCircle() {
        listOf(
            "public/assets/images/icon-maskable-192.png",
            "public/assets/images/icon-maskable-512.png",
            "public/assets/images/apple-touch-icon.png",
        ).forEach { path ->
            val tile = image(path)
            val side = tile.width
            val radius = side * 0.4
            for (y in 0 until side) {
                for (x in 0 until side) {
                    if (differsFromBlue(tile.getRGB(x, y))) {
                        val r = hypot(x + 0.5 - side / 2.0, y + 0.5 - side / 2.0)
                        assertTrue(r <= radius + 2, "$path has content at ($x,$y), r=$r > $radius")
                    }
                }
            }
        }
    }

    @Test
    fun offlinePageDeclaresTheFaviconAndKeepsTheAppleIcon() {
        val html = resource("public/offline.html")
        assertTrue(html.contains("<link rel=\"icon\" href=\"/favicon.ico\" sizes=\"any\">"))
        assertTrue(html.contains("rel=\"icon\" type=\"image/png\" sizes=\"32x32\" href=\"/assets/images/favicon-32.png\""))
        assertTrue(html.contains("rel=\"icon\" type=\"image/png\" sizes=\"16x16\" href=\"/assets/images/favicon-16.png\""))
        assertTrue(html.contains("rel=\"apple-touch-icon\" href=\"/assets/images/apple-touch-icon.png\""))
    }

    @Test
    fun offlinePageIsSelfContained() {
        val html = resource("public/offline.html")
        assertTrue(html.contains("Vous êtes hors ligne"))
        assertTrue(html.contains("data-retry"))
        assertTrue(html.contains("/assets/images/logo.png"))
        assertFalse(html.contains("fonts.googleapis.com"), "no webfonts offline")
        assertFalse(html.contains("/assets/css/"), "no bundle dependency")
        assertFalse(html.contains("<script src="), "scripts must be inline")
    }

    @Test
    fun serviceWorkerVersionMatchesTheOfflinePage() {
        val sw = resource("public/sw.js")
        val digest = MessageDigest.getInstance("SHA-256")
        digest.update(resourceBytes("public/offline.html"))
        digest.update(resourceBytes("public/assets/images/logo.png"))
        val version = digest.digest().joinToString("") { "%02x".format(it.toInt() and 0xff) }.take(12)
        assertTrue(sw.contains("const VERSION = \"$version\""), sw.take(200))
        assertTrue(sw.contains("/offline.html"))
        assertTrue(sw.contains("/assets/images/logo.png"))
    }

    /** One PNG-compressed layer of `public/favicon.ico`. */
    private data class IcoLayer(val size: Int, val bitCount: Int, val image: BufferedImage)

    private fun icoLayers(): List<IcoLayer> {
        val bytes = resourceBytes("public/favicon.ico")
        val count = bytes[4].toInt() and 0xff
        return (0 until count).map { i ->
            val at = 6 + 16 * i
            val size = bytes[at].toInt() and 0xff
            val bitCount = (bytes[at + 6].toInt() and 0xff) or ((bytes[at + 7].toInt() and 0xff) shl 8)
            val length = littleEndian(bytes, at + 8)
            val offset = littleEndian(bytes, at + 12)
            IcoLayer(size, bitCount, ImageIO.read(ByteArrayInputStream(bytes, offset, length)))
        }
    }

    /** The four delivered files, the ICO's three layers included, each under the name a failure names. */
    private fun faviconImages(): List<Pair<String, BufferedImage>> =
        listOf(
            "public/assets/images/favicon.png",
            "public/assets/images/favicon-16.png",
            "public/assets/images/favicon-32.png",
        ).map { path -> path to image(path) } +
            icoLayers().map { layer -> "the ${layer.size}px ICO layer" to layer.image }

    /** Every pixel of the four border rows and columns must be fully transparent. */
    private fun assertTransparentBorder(name: String, icon: BufferedImage) {
        val lastX = icon.width - 1
        val lastY = icon.height - 1
        for (x in 0..lastX) {
            assertEquals(0, icon.getRGB(x, 0) ushr 24, "$name is not transparent at ($x,0)")
            assertEquals(0, icon.getRGB(x, lastY) ushr 24, "$name is not transparent at ($x,$lastY)")
        }
        for (y in 1 until lastY) {
            assertEquals(0, icon.getRGB(0, y) ushr 24, "$name is not transparent at (0,$y)")
            assertEquals(0, icon.getRGB(lastX, y) ushr 24, "$name is not transparent at ($lastX,$y)")
        }
    }

    /** No pixel the browser shows may be near-white: that is the source's square or the disc's white fringe. */
    private fun assertNoVisibleWhite(name: String, icon: BufferedImage) {
        for (y in 0 until icon.height) {
            for (x in 0 until icon.width) {
                val argb = icon.getRGB(x, y)
                if (argb ushr 24 == 0) continue // the source's white RGB under a transparent pixel is invisible
                val rgb = argb and 0xFFFFFF
                val darkest = minOf((rgb shr 16) and 0xFF, (rgb shr 8) and 0xFF, rgb and 0xFF)
                assertTrue(darkest < VISIBLE_WHITE, "$name has a visible near-white pixel at ($x,$y): #%06x".format(rgb))
            }
        }
    }

    /** Reads a little-endian 32-bit integer at `at`. */
    private fun littleEndian(bytes: ByteArray, at: Int): Int =
        (bytes[at].toInt() and 0xff) or
            ((bytes[at + 1].toInt() and 0xff) shl 8) or
            ((bytes[at + 2].toInt() and 0xff) shl 16) or
            ((bytes[at + 3].toInt() and 0xff) shl 24)

    private fun image(path: String): BufferedImage =
        ImageIO.read(javaClass.classLoader.getResourceAsStream(path) ?: fail("missing classpath resource $path"))

    private fun rgb(image: BufferedImage, x: Int, y: Int): Int = image.getRGB(x, y) and 0xFFFFFF

    private fun differsFromBlue(argb: Int): Boolean =
        listOf(16, 8, 0).any { abs(((argb shr it) and 0xFF) - ((BLUE shr it) and 0xFF)) > 8 }

    private fun resource(path: String): String =
        javaClass.classLoader.getResourceAsStream(path)?.use { it.readBytes().decodeToString() }
            ?: fail("missing classpath resource $path")

    private fun resourceBytes(path: String): ByteArray =
        javaClass.classLoader.getResourceAsStream(path)?.use { it.readBytes() }
            ?: fail("missing classpath resource $path")

    /** Reads `width x height` from the PNG's IHDR chunk. */
    private fun pngSize(bytes: ByteArray): Pair<Int, Int> {
        assertEquals("PNG", String(bytes, 1, 3, Charsets.US_ASCII), "not a PNG")
        fun int(at: Int) =
            ((bytes[at].toInt() and 0xff) shl 24) or
                ((bytes[at + 1].toInt() and 0xff) shl 16) or
                ((bytes[at + 2].toInt() and 0xff) shl 8) or
                (bytes[at + 3].toInt() and 0xff)
        return int(16) to int(20)
    }
}
